from mcp.server.fastmcp import FastMCP

mcp = FastMCP("github")

@mcp.tool()
def create_issue(repo: str, title: str, body: str) -> str:
    """Open a new GitHub issue and return its URL."""
    issue = gh.create_issue(repo, title=title, body=body)
    return issue.html_url

@mcp.resource("repo://{repo}/readme")
def read_readme(repo: str) -> str:
    """Expose a repo's README as readable context."""
    return gh.get_readme(repo)

if __name__ == "__main__":
    mcp.run()  # any MCP host can now connect
